original_matcher:
// Server-side rule matcher — 對齊 heavy.html 前端 matcher
// v2 20260914_1815: 新增多維度 filter 支援（hg-01/02/09）
//   - hour_hkt: 早/午/夜/深夜
//   - tier: 頂五/頂級/低組/女足/青年/杯賽/預備/其他
//   - ou_shrink_home / ou_shrink_away / ah_shrink_home / ah_shrink_away
//   - ah_line_dir / ou_line_dir: AH線↑/AH線↓/AH線平, OU 同
//   - ah_bucket / ou_bucket: AH0/AH小(0.25-0.5)/AH中(0.75-1)/AH大(1.25-1.75)/AH極大(2+), OU 同

const toDec = (v) => {
  try { return Math.round((parseFloat(v) + 1) * 1000) / 1000; }
  catch { return null; }
};

const MIN_T5_DEC = 1.70;   // T-5 賠率下限（含）

const shrinkBucketCn = (s) => {
  if (s == null) return null;
  if (s >= 0.15) return "大收";
  if (s >= 0.05) return "中收";
  if (s >= 0.02) return "微收";
  if (s > -0.02) return "平穩";
  if (s > -0.05) return "微放";
  if (s > -0.10) return "中放";
  return "大放";
};

const leanOU = (snap) => {
  if (!snap) return null;
  const h = toDec(snap.home), a = toDec(snap.away);
  if (h == null || a == null) return null;
  if (Math.abs(h - a) < 0.02) return null;
  return h < a ? "O" : "U";
};

const leanAH = (snap) => {
  if (!snap) return null;
  const h = toDec(snap.home), a = toDec(snap.away);
  if (h == null || a == null) return null;
  if (Math.abs(h - a) < 0.02) return null;
  return h < a ? "H" : "A";
};

const hourHKT = (t) => {
  if (t == null) return null;
  const ms = typeof t === "number" ? t : Date.parse(t);
  if (!isFinite(ms)) return null;
  const h = (new Date(ms).getUTCHours() + 8) % 24;
  if (h >= 4 && h < 12) return "早";
  if (h >= 12 && h < 18) return "午";
  if (h >= 18 && h < 24) return "夜";
  return "深夜";
};

const tierOf = (league) => {
  if (!league) return "其他";
  if (["英超","西甲","意甲","德甲","法甲"].includes(league)) return "頂五";
  if (league.includes("女")) return "女足";
  if (/U\d/.test(league)) return "青年";
  if (league.includes("杯")) return "杯賽";
  if (league.endsWith("乙") || league.endsWith("丙") || league.endsWith("丁")) return "低組";
  if (league.includes("后备") || league.includes("預備") || league.includes("预备")) return "預備";
  return "頂級";
};

const lineDir = (initH, t5H, prefix) => {
  // Preserve the evidence-version meaning of existing AH線↑/↓ rules.
  // AH values are now signed home adjustments, so increasing home concession is negative.
  const move = (Number(t5H) - Number(initH)) * (prefix === "AH" ? -1 : 1);
  if (!isFinite(move)) return null;
  if (move > 0.1) return `${prefix}線↑`;
  if (move < -0.1) return `${prefix}線↓`;
  return `${prefix}線平`;
};

const ahBucketOf = (h) => {
  const abs = Math.abs(Number(h));
  if (!isFinite(abs)) return null;
  if (abs < 0.25) return "AH0";
  if (abs < 0.75) return "AH小(0.25-0.5)";
  if (abs < 1.25) return "AH中(0.75-1)";
  if (abs < 2) return "AH大(1.25-1.75)";
  return "AH極大(2+)";
};

const ouBucketOf = (h) => {
  const line = Number(h);
  if (!isFinite(line)) return null;
  if (line < 2.25) return "OU細盤";
  if (line < 2.75) return "OU中盤";
  if (line < 3.25) return "OU大盤";
  return "OU極大";
};

// 檢查 rule 有冇多維 filter，冚都符合先 return true
// rule 支援：hour_hkt, tier, ou_shrink_home, ou_shrink_away, ah_shrink_home, ah_shrink_away,
//         ah_line_dir, ou_line_dir, ah_bucket, ou_bucket, ou_pat, ah_pat
function checkMultiDimFilters(m, rule, snaps) {
  const { initOU, t30OU, t5OU, initAH, t30AH, t5AH } = snaps;

  // 時間 filter
  if (rule.hour_hkt) {
    const h = hourHKT(m.kickoff_utc || m.kickoffUtc || m.kickoff);
    if (h !== rule.hour_hkt) return false;
  }

  // 聯賽級別
  if (rule.tier) {
    const t = tierOf(m.league);
    if (t !== rule.tier) return false;
  }

  // OU 3 時點 lean pattern（獨立於 lean_pat，避免同 line_pat 綁在一起）
  // v3 20260916: rule.ou_pat / rule.ah_pat 支援 `?` 作為通配符（任何 lean 值都算 match）
  if (rule.ou_pat) {
    if (!initOU || !t30OU || !t5OU) return false;
    const p = `${leanOU(initOU) || "?"}${leanOU(t30OU) || "?"}${leanOU(t5OU) || "?"}`;
    const pat = rule.ou_pat;
    if (pat.length !== 3) return false;
    for (let i = 0; i < 3; i++) {
      if (pat[i] !== "?" && pat[i] !== p[i]) return false;
    }
  }

  // AH 3 時點 lean pattern
  if (rule.ah_pat) {
    if (!initAH || !t30AH || !t5AH) return false;
    const p = `${leanAH(initAH) || "?"}${leanAH(t30AH) || "?"}${leanAH(t5AH) || "?"}`;
    const pat = rule.ah_pat;
    if (pat.length !== 3) return false;
    for (let i = 0; i < 3; i++) {
      if (pat[i] !== "?" && pat[i] !== p[i]) return false;
    }
  }

  // OU 主客側 shrink
  if (rule.ou_shrink_home) {
    if (!initOU || !t5OU) return false;
    if (shrinkBucketCn(toDec(initOU.home) - toDec(t5OU.home)) !== rule.ou_shrink_home) return false;
  }
  if (rule.ou_shrink_away) {
    if (!initOU || !t5OU) return false;
    if (shrinkBucketCn(toDec(initOU.away) - toDec(t5OU.away)) !== rule.ou_shrink_away) return false;
  }

  // AH 主客側 shrink
  if (rule.ah_shrink_home) {
    if (!initAH || !t5AH) return false;
    if (shrinkBucketCn(toDec(initAH.home) - toDec(t5AH.home)) !== rule.ah_shrink_home) return false;
  }
  if (rule.ah_shrink_away) {
    if (!initAH || !t5AH) return false;
    if (shrinkBucketCn(toDec(initAH.away) - toDec(t5AH.away)) !== rule.ah_shrink_away) return false;
  }

  // AH / OU 盤口方向
  if (rule.ah_line_dir) {
    if (!initAH || !t5AH) return false;
    if (lineDir(initAH.h, t5AH.h, "AH") !== rule.ah_line_dir) return false;
  }
  if (rule.ou_line_dir) {
    if (!initOU || !t5OU) return false;
    if (lineDir(initOU.h, t5OU.h, "OU") !== rule.ou_line_dir) return false;
  }

  // AH / OU 盤口大小 bucket（依 T5）
  if (rule.ah_bucket) {
    if (!t5AH) return false;
    if (ahBucketOf(t5AH.h) !== rule.ah_bucket) return false;
  }
  if (rule.ou_bucket) {
    if (!t5OU) return false;
    if (ouBucketOf(t5OU.h) !== rule.ou_bucket) return false;
  }

  // AH 盤口方向：H=主讓(-), A=受讓(+), flat=平手(0)
  if (rule.ah_line_side) {
    if (!t5AH) return false;
    const l5 = Number(t5AH.h);
    let side;
    if (l5 < 0) side = "H";
    else if (l5 > 0) side = "A";
    else side = "flat";
    if (side !== rule.ah_line_side) return false;
  }

  // v3 20260916: strategy.html 4 條聲道精確對齊用嘅 filter
  //   ou_line_dir_t30_t5:  OU 盤口 T30 → T5 方向（strategy B∩I 用「T30 hcp > T5 hcp」= OU降）
  //   ah_hcp_eq_t30_t5:    AH 盤口 T30 === T5（strategy A+低盤「AH穩」）
  //   ou_hcp_le:           OU T-5 handicap ≤ 數值（strategy「低盤」= ≤2.25 / 「中盤」= 2.25<h<2.75）
  //   ou_hcp_gt:           OU T-5 handicap > 數值（配 ou_hcp_le 做 range）
  //   ah_lean_t5:          淨睇 T-5 AH lean（H/A/null）,strategy「leanAH=H」

  if (rule.ou_line_dir_t30_t5) {
    if (!t30OU || !t5OU) return false;
    const t30h = Number(t30OU.h), t5h = Number(t5OU.h);
    if (!isFinite(t30h) || !isFinite(t5h)) return false;
    // strict >  (strategy B∩I 用 `> ` 而非 `≥`)
    let dir;
    if (t30h > t5h) dir = "OU降";
    else if (t30h < t5h) dir = "OU升";
    else dir = "OU平";
    if (dir !== rule.ou_line_dir_t30_t5) return false;
  }

  if (rule.ah_hcp_eq_t30_t5) {
    if (!t30AH || !t5AH) return false;
    const t30h = Number(t30AH.h), t5h = Number(t5AH.h);
    if (!isFinite(t30h) || !isFinite(t5h)) return false;
    // rule 值:  true  → 要 exact eq；false → 要唔等
    const eq = Math.abs(t30h - t5h) < 0.001;
    if (rule.ah_hcp_eq_t30_t5 === true && !eq) return false;
    if (rule.ah_hcp_eq_t30_t5 === false && eq) return false;
  }

  if (rule.ou_hcp_le !== undefined && rule.ou_hcp_le !== null) {
    if (!t5OU) return false;
    const v = Number(t5OU.h);
    if (!isFinite(v)) return false;
    if (!(v <= Number(rule.ou_hcp_le))) return false;
  }

  if (rule.ou_hcp_gt !== undefined && rule.ou_hcp_gt !== null) {
    if (!t5OU) return false;
    const v = Number(t5OU.h);
    if (!isFinite(v)) return false;
    if (!(v > Number(rule.ou_hcp_gt))) return false;
  }

  if (rule.ah_lean_t5) {
    if (!t5AH) return false;
    const l = leanAH(t5AH);
    if (l !== rule.ah_lean_t5) return false;
  }

  return true;
}

const findSameLine = (m, stage, market, targetH) => {
  const key = `${stage}_${market}`;
  const main = m.snapshots?.[key];
  if (main && main.h === targetH) return main;
  for (const sub of Object.values(m.sublines || {})) {
    const s = sub[key];
    if (s && s.h === targetH) return s;
  }
  return null;
};

function matchOURule(m, rule) {
  const init = m.snapshots?.initial_OU;
  const t30 = m.snapshots?.T30_OU;
  const t5 = m.snapshots?.T5_OU;
  if (!init || !t30 || !t5) return null;

  // v2 分支：如果 rule 有 line_pat，跑舊 line-pattern 邏輯
  if (rule.line_pat) {
    const parts = rule.line_pat.split("→").map(Number);
    if (parts.length !== 3) return null;
    const [i, m30, m5] = parts;
    if (parseFloat(init.h) !== i) return null;
    let t30Use = t30, t5Use = t5;
    if (parseFloat(t30.h) !== m30) {
      t30Use = findSameLine(m, "T30", "OU", String(m30));
      if (!t30Use) return null;
    }
    if (parseFloat(t5.h) !== m5) {
      t5Use = findSameLine(m, "T5", "OU", String(m5));
      if (!t5Use) return null;
    }
    const li = leanOU(init), l30 = leanOU(t30Use), l5 = leanOU(t5Use);
    if (!li || !l30 || !l5) return null;
    if (rule.lean_pat && (li + l30 + l5) !== rule.lean_pat) return null;
    if (rule.shrink_bucket) {
      const useOpp = rule.shrink_side === "opp";
      const initSide = useOpp ? (li === "O" ? init.away : init.home)
                              : (li === "O" ? init.home : init.away);
      const t5Side = useOpp ? (li === "O" ? t5Use.away : t5Use.home)
                            : (li === "O" ? t5Use.home : t5Use.away);
      if (shrinkBucketCn(toDec(initSide) - toDec(t5Side)) !== rule.shrink_bucket) return null;
    }
    // 多維 filter 也要通過
    if (!checkMultiDimFilters(m, rule, { initOU: init, t30OU: t30Use, t5OU: t5Use, initAH: m.snapshots?.initial_AH, t30AH: m.snapshots?.T30_AH, t5AH: m.snapshots?.T5_AH })) return null;

    const pickIsOver = rule.side === "O";
    const initDec = toDec(pickIsOver ? init.home : init.away);
    const t5Dec = toDec(pickIsOver ? t5Use.home : t5Use.away);
    if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
    return {
      pick: pickIsOver ? "over" : "under",
      pickLabel: rule.pick_label || (pickIsOver ? "買大" : "買細"),
      line: rule.line_pat,
      lineLabel: `OU ${m5}`,
      t5Line: m5,
      initDec, t5Dec,
      shrink: initDec - t5Dec,
    };
  }

  // v2 純多維分支：只用 multi-dim filters（無 line_pat 綁定）
  if (!checkMultiDimFilters(m, rule, { initOU: init, t30OU: t30, t5OU: t5, initAH: m.snapshots?.initial_AH, t30AH: m.snapshots?.T30_AH, t5AH: m.snapshots?.T5_AH })) return null;

  const pickIsOver = rule.side === "O";
  const initDec = toDec(pickIsOver ? init.home : init.away);
  const t5Dec = toDec(pickIsOver ? t5.home : t5.away);
  if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
  return {
    pick: pickIsOver ? "over" : "under",
    pickLabel: rule.pick_label || (pickIsOver ? "買大" : "買細"),
    line: `${init.h}→${t30.h}→${t5.h}`,
    lineLabel: `OU ${t5.h}`,
    t5Line: parseFloat(t5.h),
    initDec, t5Dec,
    shrink: initDec - t5Dec,
  };
}

function matchAHRule(m, rule) {
  const init = m.snapshots?.initial_AH;
  const t30 = m.snapshots?.T30_AH;
  const t5 = m.snapshots?.T5_AH;
  if (!init || !t30 || !t5) return null;

  if (rule.line_pat) {
    // Legacy rule evidence remains immutable; translate its Titan-sign line pattern.
    const parts = rule.line_pat.split("→").map(v => -Number(v));
    if (parts.length !== 3 || parts.some(v => !Number.isFinite(v))) return null;
    const [i, m30, m5] = parts;
    if (parseFloat(init.h) !== i) return null;
    let t30Use = t30, t5Use = t5;
    if (parseFloat(t30.h) !== m30) {
      t30Use = findSameLine(m, "T30", "AH", String(m30));
      if (!t30Use) return null;
    }
    if (parseFloat(t5.h) !== m5) {
      t5Use = findSameLine(m, "T5", "AH", String(m5));
      if (!t5Use) return null;
    }
    const li = leanAH(init), l30 = leanAH(t30Use), l5 = leanAH(t5Use);
    if (!li || !l30 || !l5) return null;
    if (rule.lean_pat && (li + l30 + l5) !== rule.lean_pat) return null;
    if (rule.shrink_bucket) {
      const useOpp = rule.shrink_side === "opp";
      const initSide = useOpp ? (li === "H" ? init.away : init.home)
                              : (li === "H" ? init.home : init.away);
      const t5Side = useOpp ? (li === "H" ? t5Use.away : t5Use.home)
                            : (li === "H" ? t5Use.home : t5Use.away);
      if (shrinkBucketCn(toDec(initSide) - toDec(t5Side)) !== rule.shrink_bucket) return null;
    }
    if (!checkMultiDimFilters(m, rule, { initOU: m.snapshots?.initial_OU, t30OU: m.snapshots?.T30_OU, t5OU: m.snapshots?.T5_OU, initAH: init, t30AH: t30Use, t5AH: t5Use })) return null;

    const pickIsHome = rule.side === "H";
    const initDec = toDec(pickIsHome ? init.home : init.away);
    const t5Dec = toDec(pickIsHome ? t5Use.home : t5Use.away);
    if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
    return {
      pick: pickIsHome ? "home" : "away",
      pickLabel: rule.pick_label || (pickIsHome ? "買主" : "買客"),
      line: parts.join("→"),
      lineLabel: `AH ${m5}`,
      t5Line: m5,
      initDec, t5Dec,
      shrink: initDec - t5Dec,
    };
  }

  // 純多維分支
  if (!checkMultiDimFilters(m, rule, { initOU: m.snapshots?.initial_OU, t30OU: m.snapshots?.T30_OU, t5OU: m.snapshots?.T5_OU, initAH: init, t30AH: t30, t5AH: t5 })) return null;

  const pickIsHome = rule.side === "H";
  const initDec = toDec(pickIsHome ? init.home : init.away);
  const t5Dec = toDec(pickIsHome ? t5.home : t5.away);
  if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
  return {
    pick: pickIsHome ? "home" : "away",
    pickLabel: rule.pick_label || (pickIsHome ? "買主" : "買客"),
    line: `${init.h}→${t30.h}→${t5.h}`,
    lineLabel: `AH ${t5.h}`,
    t5Line: parseFloat(t5.h),
    initDec, t5Dec,
    shrink: initDec - t5Dec,
  };
}

// Shift-based OU rule matcher (unchanged from v1)
function matchOUShiftRule(m, rule) {
  const init = m.snapshots?.initial_OU;
  const t5 = m.snapshots?.T5_OU;
  if (!init || !t5) return null;
  const initH = parseFloat(init.h);
  const t5H = parseFloat(t5.h);
  if (!isFinite(initH) || !isFinite(t5H)) return null;
  const diff = initH - t5H;
  const minShift = parseFloat(rule.shift_min) || 0.5;
  if (rule.shift_direction === "down" && diff < minShift) return null;
  if (rule.shift_direction === "up"   && (-diff) < minShift) return null;
  const pickIsOver = rule.side === "O";
  const initDec = toDec(pickIsOver ? init.home : init.away);
  const t5Dec = toDec(pickIsOver ? t5.home : t5.away);
  if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
  return {
    pick: pickIsOver ? "over" : "under",
    pickLabel: rule.pick_label || (pickIsOver ? "買大" : "買細"),
    line: rule.line_pat || `${initH}→${t5H}`,
    lineLabel: `OU ${t5H} (${rule.shift_direction === "down" ? "落" : "加"}盤 ${Math.abs(diff)})`,
    t5Line: t5H,
    initDec, t5Dec,
    shrink: initDec - t5Dec,
  };
}

function matchAll(m, rules) {
  const hits = [];
  for (const r of rules) {
    if (r.enabled === false) continue;
    // Versioned, opt-in gates: existing channels retain their exact semantics.
    if (r.strict_six_snapshots) {
      const ko = Number(m.kickoff_utc);
      if (!Number.isFinite(ko) || (r.active_from_ms && ko < r.active_from_ms)) continue;
      let valid = true;
      for (const stage of ["initial", "T30", "T5"]) {
        for (const market of ["AH", "OU"]) {
          const s = m.snapshots?.[`${stage}_${market}`];
          if (!s || [s.h, s.home, s.away, s.captured_at].some(v =>
            v == null || v === "" || !Number.isFinite(Number(v)))) { valid = false; continue; }
          const gap = (ko - Number(s.captured_at)) / 60000;
          if (r.require_t5_after_activation && stage === "T5" &&
              Number(s.captured_at) < Number(r.active_from_ms)) valid = false;
          if (Number(s.home) <= 0 || Number(s.away) <= 0 ||
              !(stage === "initial" ? gap > 0 : stage === "T30" ? gap > 20 && gap <= 35 : gap > 0 && gap <= 8)) valid = false;
        }
      }
      if (!valid) continue;
    }
    if (r.ah_hcp_eq_t5 != null) {
      const h = m.snapshots?.T5_AH?.h;
      if (h == null || h === "" || Number(h) !== Number(r.ah_hcp_eq_t5)) continue;
    }
    let match;
    if (r.type === "ou_shift") match = matchOUShiftRule(m, r);
    else if (r.market === "AH") match = matchAHRule(m, r);
    else match = matchOURule(m, r);
    if (match && r.t5_dec_min != null && match.t5Dec < r.t5_dec_min) continue;
    if (match && r.t5_dec_max_exclusive != null && match.t5Dec >= r.t5_dec_max_exclusive) continue;
    // One OR rule, not two rules: a fixture satisfying both branches fires once.
    if (match && r.t5_under_price_or_ou_line) {
      const gate = r.t5_under_price_or_ou_line;
      const line = Number(m.snapshots?.T5_OU?.h);
      if (!(match.t5Dec >= Number(gate.min_dec) ||
            line === Number(gate.ou_line_eq))) continue;
    }
    if (match) hits.push({ rule: r, match });
  }
  return hits;
}

export { matchAll, matchOURule, matchAHRule, matchOUShiftRule };

matcher:
// Server-side rule matcher — 對齊 heavy.html 前端 matcher
// v2 20260914_1815: 新增多維度 filter 支援（hg-01/02/09）
//   - hour_hkt: 早/午/夜/深夜
//   - tier: 頂五/頂級/低組/女足/青年/杯賽/預備/其他
//   - ou_shrink_home / ou_shrink_away / ah_shrink_home / ah_shrink_away
//   - ah_line_dir / ou_line_dir: AH線↑/AH線↓/AH線平, OU 同
//   - ah_bucket / ou_bucket: AH0/AH小(0.25-0.5)/AH中(0.75-1)/AH大(1.25-1.75)/AH極大(2+), OU 同

const toDec = (v) => {
  try { return Math.round((parseFloat(v) + 1) * 1000) / 1000; }
  catch { return null; }
};

const MIN_T5_DEC = 1.70;   // T-5 賠率下限（含）

const shrinkBucketCn = (s) => {
  if (s == null) return null;
  if (s >= 0.15) return "大收";
  if (s >= 0.05) return "中收";
  if (s >= 0.02) return "微收";
  if (s > -0.02) return "平穩";
  if (s > -0.05) return "微放";
  if (s > -0.10) return "中放";
  return "大放";
};

const leanOU = (snap) => {
  if (!snap) return null;
  const h = toDec(snap.home), a = toDec(snap.away);
  if (h == null || a == null) return null;
  if (Math.abs(h - a) < 0.02) return null;
  return h < a ? "O" : "U";
};

const leanAH = (snap) => {
  if (!snap) return null;
  const h = toDec(snap.home), a = toDec(snap.away);
  if (h == null || a == null) return null;
  if (Math.abs(h - a) < 0.02) return null;
  return h < a ? "H" : "A";
};

const hourHKT = (t) => {
  if (t == null) return null;
  const ms = typeof t === "number" ? t : Date.parse(t);
  if (!isFinite(ms)) return null;
  const h = (new Date(ms).getUTCHours() + 8) % 24;
  if (h >= 4 && h < 12) return "早";
  if (h >= 12 && h < 18) return "午";
  if (h >= 18 && h < 24) return "夜";
  return "深夜";
};

const tierOf = (league) => {
  if (!league) return "其他";
  if (["英超","西甲","意甲","德甲","法甲"].includes(league)) return "頂五";
  if (league.includes("女")) return "女足";
  if (/U\d/.test(league)) return "青年";
  if (league.includes("杯")) return "杯賽";
  if (league.endsWith("乙") || league.endsWith("丙") || league.endsWith("丁")) return "低組";
  if (league.includes("后备") || league.includes("預備") || league.includes("预备")) return "預備";
  return "頂級";
};

const lineDir = (initH, t5H, prefix) => {
  // Preserve the evidence-version meaning of existing AH線↑/↓ rules.
  // AH values are now signed home adjustments, so increasing home concession is negative.
  const move = (Number(t5H) - Number(initH)) * (prefix === "AH" ? -1 : 1);
  if (!isFinite(move)) return null;
  if (move > 0.1) return `${prefix}線↑`;
  if (move < -0.1) return `${prefix}線↓`;
  return `${prefix}線平`;
};

const ahBucketOf = (h) => {
  const abs = Math.abs(Number(h));
  if (!isFinite(abs)) return null;
  if (abs < 0.25) return "AH0";
  if (abs < 0.75) return "AH小(0.25-0.5)";
  if (abs < 1.25) return "AH中(0.75-1)";
  if (abs < 2) return "AH大(1.25-1.75)";
  return "AH極大(2+)";
};

const ouBucketOf = (h) => {
  const line = Number(h);
  if (!isFinite(line)) return null;
  if (line < 2.25) return "OU細盤";
  if (line < 2.75) return "OU中盤";
  if (line < 3.25) return "OU大盤";
  return "OU極大";
};

// 檢查 rule 有冇多維 filter，冚都符合先 return true
// rule 支援：hour_hkt, tier, ou_shrink_home, ou_shrink_away, ah_shrink_home, ah_shrink_away,
//         ah_line_dir, ou_line_dir, ah_bucket, ou_bucket, ou_pat, ah_pat
function checkMultiDimFilters(m, rule, snaps) {
  const { initOU, t30OU, t5OU, initAH, t30AH, t5AH } = snaps;

  // 時間 filter
  if (rule.hour_hkt) {
    const h = hourHKT(m.kickoff_utc || m.kickoffUtc || m.kickoff);
    if (h !== rule.hour_hkt) return false;
  }
  // Opt-in exact HKT kickoff window; legacy bucket rules remain unchanged.
  if (rule.hour_hkt_min != null || rule.hour_hkt_max_exclusive != null) {
    const value = m.kickoff_utc ?? m.kickoffUtc ?? m.kickoff;
    const ms = typeof value === "number" ? value : Date.parse(value);
    if (!Number.isFinite(ms)) return false;
    const hour = (new Date(ms).getUTCHours() + 8) % 24;
    if (rule.hour_hkt_min != null && hour < Number(rule.hour_hkt_min)) return false;
    if (rule.hour_hkt_max_exclusive != null && hour >= Number(rule.hour_hkt_max_exclusive)) return false;
  }
  // Reactivation is prospective only. This gate is NOT applied to other versions.
  if (rule.require_t5_after_version) {
    const from = Number(rule.version_effective_at_ms);
    const ko = Number(m.kickoff_utc);
    const at = Number((rule.market === "AH" ? t5AH : t5OU)?.captured_at);
    if (!(from > 0 && Number.isFinite(ko) && Number.isFinite(at) &&
          ko > from && at >= from && at < ko)) return false;
  }

  // 聯賽級別
  if (rule.tier) {
    const t = tierOf(m.league);
    if (t !== rule.tier) return false;
  }

  // OU 3 時點 lean pattern（獨立於 lean_pat，避免同 line_pat 綁在一起）
  // v3 20260916: rule.ou_pat / rule.ah_pat 支援 `?` 作為通配符（任何 lean 值都算 match）
  if (rule.ou_pat) {
    if (!initOU || !t30OU || !t5OU) return false;
    const p = `${leanOU(initOU) || "?"}${leanOU(t30OU) || "?"}${leanOU(t5OU) || "?"}`;
    const pat = rule.ou_pat;
    if (pat.length !== 3) return false;
    for (let i = 0; i < 3; i++) {
      if (pat[i] !== "?" && pat[i] !== p[i]) return false;
    }
  }

  // AH 3 時點 lean pattern
  if (rule.ah_pat) {
    if (!initAH || !t30AH || !t5AH) return false;
    const p = `${leanAH(initAH) || "?"}${leanAH(t30AH) || "?"}${leanAH(t5AH) || "?"}`;
    const pat = rule.ah_pat;
    if (pat.length !== 3) return false;
    for (let i = 0; i < 3; i++) {
      if (pat[i] !== "?" && pat[i] !== p[i]) return false;
    }
  }

  // OU 主客側 shrink
  if (rule.ou_shrink_home) {
    if (!initOU || !t5OU) return false;
    if (shrinkBucketCn(toDec(initOU.home) - toDec(t5OU.home)) !== rule.ou_shrink_home) return false;
  }
  if (rule.ou_shrink_away) {
    if (!initOU || !t5OU) return false;
    if (shrinkBucketCn(toDec(initOU.away) - toDec(t5OU.away)) !== rule.ou_shrink_away) return false;
  }

  // AH 主客側 shrink
  if (rule.ah_shrink_home) {
    if (!initAH || !t5AH) return false;
    if (shrinkBucketCn(toDec(initAH.home) - toDec(t5AH.home)) !== rule.ah_shrink_home) return false;
  }
  if (rule.ah_shrink_away) {
    if (!initAH || !t5AH) return false;
    if (shrinkBucketCn(toDec(initAH.away) - toDec(t5AH.away)) !== rule.ah_shrink_away) return false;
  }

  // AH / OU 盤口方向
  if (rule.ah_line_dir) {
    if (!initAH || !t5AH) return false;
    if (lineDir(initAH.h, t5AH.h, "AH") !== rule.ah_line_dir) return false;
  }
  if (rule.ou_line_dir) {
    if (!initOU || !t5OU) return false;
    if (lineDir(initOU.h, t5OU.h, "OU") !== rule.ou_line_dir) return false;
  }

  // AH / OU 盤口大小 bucket（依 T5）
  if (rule.ah_bucket) {
    if (!t5AH) return false;
    if (ahBucketOf(t5AH.h) !== rule.ah_bucket) return false;
  }
  if (rule.ou_bucket) {
    if (!t5OU) return false;
    if (ouBucketOf(t5OU.h) !== rule.ou_bucket) return false;
  }

  // AH 盤口方向：H=主讓(-), A=受讓(+), flat=平手(0)
  if (rule.ah_line_side) {
    if (!t5AH) return false;
    const l5 = Number(t5AH.h);
    let side;
    if (l5 < 0) side = "H";
    else if (l5 > 0) side = "A";
    else side = "flat";
    if (side !== rule.ah_line_side) return false;
  }

  // v3 20260916: strategy.html 4 條聲道精確對齊用嘅 filter
  //   ou_line_dir_t30_t5:  OU 盤口 T30 → T5 方向（strategy B∩I 用「T30 hcp > T5 hcp」= OU降）
  //   ah_hcp_eq_t30_t5:    AH 盤口 T30 === T5（strategy A+低盤「AH穩」）
  //   ou_hcp_le:           OU T-5 handicap ≤ 數值（strategy「低盤」= ≤2.25 / 「中盤」= 2.25<h<2.75）
  //   ou_hcp_gt:           OU T-5 handicap > 數值（配 ou_hcp_le 做 range）
  //   ah_lean_t5:          淨睇 T-5 AH lean（H/A/null）,strategy「leanAH=H」

  if (rule.ou_line_dir_t30_t5) {
    if (!t30OU || !t5OU) return false;
    const t30h = Number(t30OU.h), t5h = Number(t5OU.h);
    if (!isFinite(t30h) || !isFinite(t5h)) return false;
    // strict >  (strategy B∩I 用 `> ` 而非 `≥`)
    let dir;
    if (t30h > t5h) dir = "OU降";
    else if (t30h < t5h) dir = "OU升";
    else dir = "OU平";
    if (dir !== rule.ou_line_dir_t30_t5) return false;
  }

  if (rule.ah_hcp_eq_t30_t5) {
    if (!t30AH || !t5AH) return false;
    const t30h = Number(t30AH.h), t5h = Number(t5AH.h);
    if (!isFinite(t30h) || !isFinite(t5h)) return false;
    // rule 值:  true  → 要 exact eq；false → 要唔等
    const eq = Math.abs(t30h - t5h) < 0.001;
    if (rule.ah_hcp_eq_t30_t5 === true && !eq) return false;
    if (rule.ah_hcp_eq_t30_t5 === false && eq) return false;
  }

  if (rule.ou_hcp_le !== undefined && rule.ou_hcp_le !== null) {
    if (!t5OU) return false;
    const v = Number(t5OU.h);
    if (!isFinite(v)) return false;
    if (!(v <= Number(rule.ou_hcp_le))) return false;
  }

  if (rule.ou_hcp_gt !== undefined && rule.ou_hcp_gt !== null) {
    if (!t5OU) return false;
    const v = Number(t5OU.h);
    if (!isFinite(v)) return false;
    if (!(v > Number(rule.ou_hcp_gt))) return false;
  }

  if (rule.ah_lean_t5) {
    if (!t5AH) return false;
    const l = leanAH(t5AH);
    if (l !== rule.ah_lean_t5) return false;
  }

  return true;
}

const findSameLine = (m, stage, market, targetH) => {
  const key = `${stage}_${market}`;
  const main = m.snapshots?.[key];
  if (main && main.h === targetH) return main;
  for (const sub of Object.values(m.sublines || {})) {
    const s = sub[key];
    if (s && s.h === targetH) return s;
  }
  return null;
};

function matchOURule(m, rule) {
  const init = m.snapshots?.initial_OU;
  const t30 = m.snapshots?.T30_OU;
  const t5 = m.snapshots?.T5_OU;
  if (!init || !t30 || !t5) return null;

  // v2 分支：如果 rule 有 line_pat，跑舊 line-pattern 邏輯
  if (rule.line_pat) {
    const parts = rule.line_pat.split("→").map(Number);
    if (parts.length !== 3) return null;
    const [i, m30, m5] = parts;
    if (parseFloat(init.h) !== i) return null;
    let t30Use = t30, t5Use = t5;
    if (parseFloat(t30.h) !== m30) {
      t30Use = findSameLine(m, "T30", "OU", String(m30));
      if (!t30Use) return null;
    }
    if (parseFloat(t5.h) !== m5) {
      t5Use = findSameLine(m, "T5", "OU", String(m5));
      if (!t5Use) return null;
    }
    const li = leanOU(init), l30 = leanOU(t30Use), l5 = leanOU(t5Use);
    if (!li || !l30 || !l5) return null;
    if (rule.lean_pat && (li + l30 + l5) !== rule.lean_pat) return null;
    if (rule.shrink_bucket) {
      const useOpp = rule.shrink_side === "opp";
      const initSide = useOpp ? (li === "O" ? init.away : init.home)
                              : (li === "O" ? init.home : init.away);
      const t5Side = useOpp ? (li === "O" ? t5Use.away : t5Use.home)
                            : (li === "O" ? t5Use.home : t5Use.away);
      if (shrinkBucketCn(toDec(initSide) - toDec(t5Side)) !== rule.shrink_bucket) return null;
    }
    // 多維 filter 也要通過
    if (!checkMultiDimFilters(m, rule, { initOU: init, t30OU: t30Use, t5OU: t5Use, initAH: m.snapshots?.initial_AH, t30AH: m.snapshots?.T30_AH, t5AH: m.snapshots?.T5_AH })) return null;

    const pickIsOver = rule.side === "O";
    const initDec = toDec(pickIsOver ? init.home : init.away);
    const t5Dec = toDec(pickIsOver ? t5Use.home : t5Use.away);
    if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
    return {
      pick: pickIsOver ? "over" : "under",
      pickLabel: rule.pick_label || (pickIsOver ? "買大" : "買細"),
      line: rule.line_pat,
      lineLabel: `OU ${m5}`,
      t5Line: m5,
      initDec, t5Dec,
      shrink: initDec - t5Dec,
    };
  }

  // v2 純多維分支：只用 multi-dim filters（無 line_pat 綁定）
  if (!checkMultiDimFilters(m, rule, { initOU: init, t30OU: t30, t5OU: t5, initAH: m.snapshots?.initial_AH, t30AH: m.snapshots?.T30_AH, t5AH: m.snapshots?.T5_AH })) return null;

  const pickIsOver = rule.side === "O";
  const initDec = toDec(pickIsOver ? init.home : init.away);
  const t5Dec = toDec(pickIsOver ? t5.home : t5.away);
  if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
  return {
    pick: pickIsOver ? "over" : "under",
    pickLabel: rule.pick_label || (pickIsOver ? "買大" : "買細"),
    line: `${init.h}→${t30.h}→${t5.h}`,
    lineLabel: `OU ${t5.h}`,
    t5Line: parseFloat(t5.h),
    initDec, t5Dec,
    shrink: initDec - t5Dec,
  };
}

function matchAHRule(m, rule) {
  const init = m.snapshots?.initial_AH;
  const t30 = m.snapshots?.T30_AH;
  const t5 = m.snapshots?.T5_AH;
  if (!init || !t30 || !t5) return null;

  if (rule.line_pat) {
    // Legacy rule evidence remains immutable; translate its Titan-sign line pattern.
    const parts = rule.line_pat.split("→").map(v => -Number(v));
    if (parts.length !== 3 || parts.some(v => !Number.isFinite(v))) return null;
    const [i, m30, m5] = parts;
    if (parseFloat(init.h) !== i) return null;
    let t30Use = t30, t5Use = t5;
    if (parseFloat(t30.h) !== m30) {
      t30Use = findSameLine(m, "T30", "AH", String(m30));
      if (!t30Use) return null;
    }
    if (parseFloat(t5.h) !== m5) {
      t5Use = findSameLine(m, "T5", "AH", String(m5));
      if (!t5Use) return null;
    }
    const li = leanAH(init), l30 = leanAH(t30Use), l5 = leanAH(t5Use);
    if (!li || !l30 || !l5) return null;
    if (rule.lean_pat && (li + l30 + l5) !== rule.lean_pat) return null;
    if (rule.shrink_bucket) {
      const useOpp = rule.shrink_side === "opp";
      const initSide = useOpp ? (li === "H" ? init.away : init.home)
                              : (li === "H" ? init.home : init.away);
      const t5Side = useOpp ? (li === "H" ? t5Use.away : t5Use.home)
                            : (li === "H" ? t5Use.home : t5Use.away);
      if (shrinkBucketCn(toDec(initSide) - toDec(t5Side)) !== rule.shrink_bucket) return null;
    }
    if (!checkMultiDimFilters(m, rule, { initOU: m.snapshots?.initial_OU, t30OU: m.snapshots?.T30_OU, t5OU: m.snapshots?.T5_OU, initAH: init, t30AH: t30Use, t5AH: t5Use })) return null;

    const pickIsHome = rule.side === "H";
    const initDec = toDec(pickIsHome ? init.home : init.away);
    const t5Dec = toDec(pickIsHome ? t5Use.home : t5Use.away);
    if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
    return {
      pick: pickIsHome ? "home" : "away",
      pickLabel: rule.pick_label || (pickIsHome ? "買主" : "買客"),
      line: parts.join("→"),
      lineLabel: `AH ${m5}`,
      t5Line: m5,
      initDec, t5Dec,
      shrink: initDec - t5Dec,
    };
  }

  // 純多維分支
  if (!checkMultiDimFilters(m, rule, { initOU: m.snapshots?.initial_OU, t30OU: m.snapshots?.T30_OU, t5OU: m.snapshots?.T5_OU, initAH: init, t30AH: t30, t5AH: t5 })) return null;

  const pickIsHome = rule.side === "H";
  const initDec = toDec(pickIsHome ? init.home : init.away);
  const t5Dec = toDec(pickIsHome ? t5.home : t5.away);
  if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
  return {
    pick: pickIsHome ? "home" : "away",
    pickLabel: rule.pick_label || (pickIsHome ? "買主" : "買客"),
    line: `${init.h}→${t30.h}→${t5.h}`,
    lineLabel: `AH ${t5.h}`,
    t5Line: parseFloat(t5.h),
    initDec, t5Dec,
    shrink: initDec - t5Dec,
  };
}

// Shift-based OU rule matcher (unchanged from v1)
function matchOUShiftRule(m, rule) {
  const init = m.snapshots?.initial_OU;
  const t5 = m.snapshots?.T5_OU;
  if (!init || !t5) return null;
  const initH = parseFloat(init.h);
  const t5H = parseFloat(t5.h);
  if (!isFinite(initH) || !isFinite(t5H)) return null;
  const diff = initH - t5H;
  const minShift = parseFloat(rule.shift_min) || 0.5;
  if (rule.shift_direction === "down" && diff < minShift) return null;
  if (rule.shift_direction === "up"   && (-diff) < minShift) return null;
  const pickIsOver = rule.side === "O";
  const initDec = toDec(pickIsOver ? init.home : init.away);
  const t5Dec = toDec(pickIsOver ? t5.home : t5.away);
  if (!isFinite(t5Dec) || t5Dec < MIN_T5_DEC) return null;
  return {
    pick: pickIsOver ? "over" : "under",
    pickLabel: rule.pick_label || (pickIsOver ? "買大" : "買細"),
    line: rule.line_pat || `${initH}→${t5H}`,
    lineLabel: `OU ${t5H} (${rule.shift_direction === "down" ? "落" : "加"}盤 ${Math.abs(diff)})`,
    t5Line: t5H,
    initDec, t5Dec,
    shrink: initDec - t5Dec,
  };
}

function matchAll(m, rules) {
  const hits = [];
  for (const r of rules) {
    if (r.enabled === false) continue;
    // Versioned, opt-in gates: existing channels retain their exact semantics.
    if (r.strict_six_snapshots) {
      const ko = Number(m.kickoff_utc);
      if (!Number.isFinite(ko) || (r.active_from_ms && ko < r.active_from_ms)) continue;
      let valid = true;
      for (const stage of ["initial", "T30", "T5"]) {
        for (const market of ["AH", "OU"]) {
          const s = m.snapshots?.[`${stage}_${market}`];
          if (!s || [s.h, s.home, s.away, s.captured_at].some(v =>
            v == null || v === "" || !Number.isFinite(Number(v)))) { valid = false; continue; }
          const gap = (ko - Number(s.captured_at)) / 60000;
          if (r.require_t5_after_activation && stage === "T5" &&
              Number(s.captured_at) < Number(r.active_from_ms)) valid = false;
          if (Number(s.home) <= 0 || Number(s.away) <= 0 ||
              !(stage === "initial" ? gap > 0 : stage === "T30" ? gap > 20 && gap <= 35 : gap > 0 && gap <= 8)) valid = false;
        }
      }
      if (!valid) continue;
    }
    if (r.ah_hcp_eq_t5 != null) {
      const h = m.snapshots?.T5_AH?.h;
      if (h == null || h === "" || Number(h) !== Number(r.ah_hcp_eq_t5)) continue;
    }
    let match;
    if (r.type === "ou_shift") match = matchOUShiftRule(m, r);
    else if (r.market === "AH") match = matchAHRule(m, r);
    else match = matchOURule(m, r);
    if (match && r.t5_dec_min != null && match.t5Dec < r.t5_dec_min) continue;
    if (match && r.t5_dec_max_exclusive != null && match.t5Dec >= r.t5_dec_max_exclusive) continue;
    // One OR rule, not two rules: a fixture satisfying both branches fires once.
    if (match && r.t5_under_price_or_ou_line) {
      const gate = r.t5_under_price_or_ou_line;
      const line = Number(m.snapshots?.T5_OU?.h);
      if (!(match.t5Dec >= Number(gate.min_dec) ||
            line === Number(gate.ou_line_eq))) continue;
    }
    if (match) hits.push({ rule: r, match });
  }
  return hits;
}

export { matchAll, matchOURule, matchAHRule, matchOUShiftRule };

