if (url.pathname === "/api/strategy-2plus-overlap") {
  // 4 條聲道 backtest：過去 30 日已完場皇冠 T-5 觸發 (Crown 觸發 + Pin 對照)
  // 聲道: B∩I / A+低盤 / 新2 / 新3
  // 落注邏輯: 每條聲道獨立開注, 同場多聲道 fire = 分別開多注 (總注額 = 聲道數 × HK$1,000)
  try {
    const toDec = (v) => { const n = parseFloat(v); if (!isFinite(n)) return null; return Math.round((n + 1) * 1000) / 1000; };
    const hourHKT = (t) => { if (t == null) return null; return (new Date(t).getUTCHours() + 8) % 24; };
    const timeBucket = (t) => { const h = hourHKT(t); if (h == null) return null; if (h >= 0 && h < 4) return "深夜"; if (h >= 4 && h < 12) return "早段"; if (h >= 12 && h < 19) return "日間"; return "晚間"; };
    const leanAH = (s) => { if (!s) return null; const h = toDec(s.home_odds), a = toDec(s.away_odds); if (h==null||a==null) return null; if (Math.abs(h-a)<0.02) return null; return h<a?"H":"A"; };
    const leanOU = (s) => { if (!s) return null; const h = toDec(s.home_odds), a = toDec(s.away_odds); if (h==null||a==null) return null; if (Math.abs(h-a)<0.02) return null; return h<a?"O":"U"; };
    const ouHL = (hcp) => { const a = parseFloat(hcp||0); if (a >= 2.75) return "高盤"; if (a <= 2.25) return "低盤"; return "中盤"; };
    const ahSide = (hcp) => { const a = parseFloat(hcp||0); if (a < -0.001) return "H讓"; if (a > 0.001) return "A讓"; return "平手"; };
    const MIN_T5 = 1.70;
    const STAKE = 1000;
    const pnl = (r, dec, stake=STAKE) => { if (r==="W") return stake*(dec-1); if (r==="HW") return (stake/2)*(dec-1); if (r==="P") return 0; if (r==="HL") return -stake/2; if (r==="L") return -stake; return null; };
    const gradeAH = (hs, as_, hcp, side) => {
      hcp = parseFloat(hcp||0);
      const ss = side==="H"?1:-1;
      const hasQ = (Math.abs(hcp*4))%2===1;
      if (hasQ) {
        const l1 = Math.floor(hcp*2)/2, l2 = Math.ceil(hcp*2)/2;
        const m1 = ss*(hs-as_+l1), m2 = ss*(hs-as_+l2);
        const g = (m)=>m>0?"W":m<0?"L":"P";
        const g1 = g(m1), g2 = g(m2);
        if (g1==="W"&&g2==="W") return "W";
        if (g1==="L"&&g2==="L") return "L";
        if ((g1==="W"&&g2==="P")||(g1==="P"&&g2==="W")) return "HW";
        if ((g1==="L"&&g2==="P")||(g1==="P"&&g2==="L")) return "HL";
        return "P";
      }
      const m = ss*(hs-as_+hcp);
      return m>0?"W":m<0?"L":"P";
    };
    const gradeOU = (hs, as_, hcp, side) => {
      const tot = hs + as_;
      hcp = Math.abs(parseFloat(hcp||0));
      const ss = side==="O"?1:-1;
      const hasQ = (Math.abs(hcp*4))%2===1;
      if (hasQ) {
        const l1 = Math.floor(hcp*2)/2, l2 = Math.ceil(hcp*2)/2;
        const m1 = ss*(tot-l1), m2 = ss*(tot-l2);
        const g = (m)=>m>0?"W":m<0?"L":"P";
        const g1 = g(m1), g2 = g(m2);
        if (g1==="W"&&g2==="W") return "W";
        if (g1==="L"&&g2==="L") return "L";
        if ((g1==="W"&&g2==="P")||(g1==="P"&&g2==="W")) return "HW";
        if ((g1==="L"&&g2==="P")||(g1==="P"&&g2==="L")) return "HL";
        return "P";
      }
      const m = ss*(tot-hcp);
      return m>0?"W":m<0?"L":"P";
    };
    const now = Date.now();
    const startTime = now - 30 * 24 * 3600 * 1000;
    const matches = db.prepare(`
      SELECT m.sid, m.league, m.home, m.away, m.kickoff_utc,
             f.home_score, f.away_score, f.status
      FROM matches m JOIN finished_matches f ON f.sid = m.sid
      WHERE m.has_crown = 1 AND m.kickoff_utc >= ? AND m.kickoff_utc <= ?
        AND f.status = '完' AND f.home_score IS NOT NULL AND f.away_score IS NOT NULL
      ORDER BY m.kickoff_utc DESC
    `).all(startTime, now);
    const sids = matches.map(m => m.sid);
    const pinBy = new Map(), crownBy = new Map();
    if (sids.length) {
      const chunk = (arr, n) => { const o=[]; for (let i=0;i<arr.length;i+=n) o.push(arr.slice(i,i+n)); return o; };
      for (const c of chunk(sids, 500)) {
        const q = c.map(()=>"?").join(",");
        for (const r of db.prepare(`SELECT sid,stage,market,handicap,home_odds,away_odds FROM odds_snapshots WHERE sid IN (${q})`).all(...c)) {
          if (!pinBy.has(r.sid)) pinBy.set(r.sid, {});
          pinBy.get(r.sid)[`${r.stage}_${r.market}`] = r;
        }
        for (const r of db.prepare(`SELECT sid,stage,market,handicap,home_odds,away_odds FROM crown_snapshots WHERE sid IN (${q})`).all(...c)) {
          if (!crownBy.has(r.sid)) crownBy.set(r.sid, {});
          crownBy.get(r.sid)[`${r.stage}_${r.market}`] = r;
        }
      }
    }

    // Channel definitions
    // Each channel returns { fire: bool, market: 'AH'|'OU', side: 'H'|'A'|'O'|'U', bet_display }
    const CHANNELS = [
      {
        id: "B∩I", label: "B∩I (深夜 lean=O + OU降 + 買大)",
        check: (ctx) => {
          const { cT5OU, iOU } = ctx;
          if (!cT5OU || !iOU) return false;
          const t5line = parseFloat(cT5OU.handicap||0), iline = parseFloat(iOU.handicap||0);
          const ou_shift = t5line - iline;
          const ouLn = leanOU(cT5OU);
          const oddsO = toDec(cT5OU.home_odds);
          const tb = ctx.timeBk;
          return ouLn === "O" && ou_shift < -0.001 && tb === "深夜" && oddsO != null && oddsO >= MIN_T5;
        },
        market: "OU", side: "O", display: "買大",
      },
      {
        id: "A+低盤", label: "A+低盤 (平手 + AH穩 + OU低盤 + 買主)",
        check: (ctx) => {
          const { cT5AH, iAH, cT5OU } = ctx;
          if (!cT5AH || !iAH || !cT5OU) return false;
          const t5line = parseFloat(cT5AH.handicap||0), iline = parseFloat(iAH.handicap||0);
          const ah_shift = t5line - iline;
          const oddsH = toDec(cT5AH.home_odds);
          return ahSide(cT5AH.handicap) === "平手" && Math.abs(ah_shift) < 0.001 && ouHL(cT5OU.handicap) === "低盤" && oddsH != null && oddsH >= MIN_T5;
        },
        market: "AH", side: "H", display: "買主",
      },
      {
        id: "新2", label: "新2 v2 (HKT 08:00至11:59 + OU≤2.25 + 大賠≥1.70)",
        check: (ctx) => {
          const { cT5OU } = ctx;
          if (!cT5OU) return false;
          const oddsO = toDec(cT5OU.home_odds);
          const h = hourHKT(ctx.m.kickoff_utc);
          return h >= 8 && h < 12 && ouHL(cT5OU.handicap) === "低盤" && oddsO != null && oddsO >= MIN_T5;
        },
        market: "OU", side: "O", display: "買大",
      },
      {
        id: "受讓075買細", label: "受讓075買細 v2 (主受讓+0.75；細賠1.80至低於1.90 或 大小盤固定2.75；底線1.70≤細賠<1.90)",
        check: (ctx) => {
          const { cT5AH, cT5OU } = ctx;
          if (!cT5AH || !cT5OU) return false;
          const oddsU = toDec(cT5OU.away_odds);
          return Number(cT5AH.handicap) === 0.75 && oddsU != null && oddsU >= 1.70 && oddsU < 1.90 &&
            (oddsU >= 1.80 || Number(cT5OU.handicap) === 2.75);
        },
        market: "OU", side: "U", display: "買細",
      },
      {
        id: "受讓075買細（舊版已停用）",
        label: "受讓075買細 v1（舊版通知實績，與新版分開）",
        archived: true,
        market: "OU", side: "U", display: "買細",
      },
    ];

    CHANNELS.push({
      id: "新2（舊版已停用）", label: "新2 v1（重開前通知紀錄）",
      archived: true, market: "OU", side: "O", display: "買大",
    });
    // FIX 2026-09-17: 只保留 TG 真正發過嘅 (sid, channel) pair
    const CHID2RULE = { "B∩I": "ch-BI", "A+低盤": "ch-Alow", "新2": "ch-N2",
      "受讓075買細": "ch-U075-v2", "受讓075買細（舊版已停用）": "ch-U075-v1",
      "新2（舊版已停用）": "ch-N2" };
    // FIX 2026-09-17: 隱藏 rules.json 內 disabled 嘅 rule
    let disabledRuleIds = new Set();
    let n2VersionAt = Infinity;
    try {
      const rulesData = JSON.parse(fs.readFileSync("./data/rules.json", "utf-8"));
      for (const r of (rulesData.rules||[])) {
        if (r.enabled === false) disabledRuleIds.add(r.id);
        if (r.id === "ch-N2" && r.require_t5_after_version &&
            Number(r.version_effective_at_ms) > 0) n2VersionAt = Number(r.version_effective_at_ms);
      }
    } catch(e) {}
    const notifiedSet = new Set();
    const n2NotifiedAt = new Map();
    if (sids.length) {
      const chunk2 = (arr, n) => { const o=[]; for (let i=0;i<arr.length;i+=n) o.push(arr.slice(i,i+n)); return o; };
      for (const c of chunk2(sids, 500)) {
        const q = c.map(()=>"?").join(",");
        for (const r of db.prepare(`SELECT sid, rules_json FROM heavy_notified WHERE sid IN (${q})`).all(...c)) {
          try {
            const arr = JSON.parse(r.rules_json||"[]");
            for (const ruleId of arr) notifiedSet.add(`${r.sid}::${ruleId}`);
          } catch(e) {}
        }
      }
    }

    // New version counts only its own successful notification rows, never legacy 新3.
    for (const r of db.prepare("SELECT sid,rule_id FROM heavy_notified_rule WHERE rule_id IN (?,?)").all("ch-U075-v1", "ch-U075-v2")) {
      notifiedSet.add(`${r.sid}::${r.rule_id}`);
    }
    // Per-rule timestamps, not the mutable whole-match notification row.
    for (const r of db.prepare("SELECT sid,notified_at FROM heavy_notified_rule WHERE rule_id=?").all("ch-N2")) {
      notifiedSet.add(`${r.sid}::ch-N2`);
      n2NotifiedAt.set(r.sid, Number(r.notified_at));
    }

    // 2026-09-17: HKJC join · titan_id → hkjc_sid
    const titan2hkjc = new Map();
    const hkjcBy = new Map();
    if (sids.length) {
      const chunk3 = (arr, n) => { const o=[]; for (let i=0;i<arr.length;i+=n) o.push(arr.slice(i,i+n)); return o; };
      for (const c of chunk3(sids, 500)) {
        const q = c.map(()=>"?").join(",");
        for (const r of db.prepare(`SELECT titan_id, sid AS hkjc_sid FROM titan_matches WHERE titan_id IN (${q})`).all(...c)) {
          titan2hkjc.set(r.titan_id, r.hkjc_sid);
        }
      }
      const hkjcSids = Array.from(new Set(titan2hkjc.values()));
      for (const c of chunk3(hkjcSids, 500)) {
        const q = c.map(()=>"?").join(",");
        for (const r of db.prepare(`SELECT sid,stage,market,handicap,home_odds,away_odds FROM hkjc_snapshots WHERE provider='hkjc' AND sid IN (${q})`).all(...c)) {
          if (!hkjcBy.has(r.sid)) hkjcBy.set(r.sid, {});
          hkjcBy.get(r.sid)[`${r.stage}_${r.market}`] = r;
        }
      }
    }

    // 2026-09-17: hkjc_titan snapshots (sid=titan:{titan_id}) + fuzzy nameMap fallback
    const chunk4 = (arr, n) => { const o=[]; for (let i=0;i<arr.length;i+=n) o.push(arr.slice(i,i+n)); return o; };
    const titanSids2 = sids.map(s => "titan:" + s);
    for (const c of chunk4(titanSids2, 500)) {
      const q = c.map(()=>"?").join(",");
      for (const r of db.prepare(`SELECT sid,stage,market,handicap,home_odds,away_odds FROM hkjc_snapshots WHERE provider='hkjc_titan' AND sid IN (${q})`).all(...c)) {
        if (!hkjcBy.has(r.sid)) hkjcBy.set(r.sid, {});
        hkjcBy.get(r.sid)[`${r.stage}_${r.market}`] = r;
      }
    }

    // fuzzy name fallback · titan_matches 冇 map · s2t 首字 + kickoff ±30min 搵 hkjc_matches
    const s2tStr = (s) => String(s||"").split("").map(c => S2T[c] || c).join("").toLowerCase();
    const headChar = (s) => s2tStr(String(s||"").replace(/\[[^\]]*\]/g, "").replace(/[FCACSCCFHDU\s　\-\(\)（）]/g, "").trim()).slice(0, 1);
    const nameMap = new Map();
    const unmapped = matches.filter(m => !titan2hkjc.has(m.sid));
    if (unmapped.length > 0) {
      const koMin = Math.min(...unmapped.map(m => m.kickoff_utc)) - 30 * 60_000;
      const koMax = Math.max(...unmapped.map(m => m.kickoff_utc)) + 30 * 60_000;
      const hkjcCands = db.prepare(`SELECT sid, home, away, kickoff_utc FROM hkjc_matches WHERE kickoff_utc BETWEEN ? AND ?`).all(koMin, koMax);
      for (const m of unmapped) {
        const mh = headChar(m.home), ma = headChar(m.away);
        let cands = hkjcCands.filter(h =>
          Math.abs(h.kickoff_utc - m.kickoff_utc) <= 30 * 60_000 &&
          ((headChar(h.home) === mh && headChar(h.away) === ma) ||
           (headChar(h.home) === ma && headChar(h.away) === mh))
        );
        if (cands.length >= 1) {
          cands.sort((a,b) => Math.abs(a.kickoff_utc - m.kickoff_utc) - Math.abs(b.kickoff_utc - m.kickoff_utc));
          nameMap.set(m.sid, cands[0].sid);
        }
      }
      const fuzzyHkjcSids = Array.from(new Set(nameMap.values()));
      for (const c of chunk4(fuzzyHkjcSids, 500)) {
        const q = c.map(()=>"?").join(",");
        for (const r of db.prepare(`SELECT sid,stage,market,handicap,home_odds,away_odds FROM hkjc_snapshots WHERE provider='hkjc' AND sid IN (${q})`).all(...c)) {
          if (!hkjcBy.has(r.sid)) hkjcBy.set(r.sid, {});
          hkjcBy.get(r.sid)[`${r.stage}_${r.market}`] = r;
        }
      }
    }

    const games = [];  // one row per (match × channel that fires AND TG notified)
    for (const m of matches) {
      const pin = pinBy.get(m.sid) || {}, crown = crownBy.get(m.sid) || {};
      const hkjcSid = titan2hkjc.get(m.sid) || (typeof nameMap !== "undefined" ? nameMap.get(m.sid) : null);
      const hkjcTitanKey = "titan:" + m.sid;
      // 先用 hkjc_titan (新 · 直接對 titan_id) · 冇就 fallback 舊 provider=hkjc via titan_matches OR fuzzy nameMap
      const hkjc = hkjcBy.get(hkjcTitanKey) || (hkjcSid ? (hkjcBy.get(hkjcSid) || {}) : {});
      const cT5AH = crown.T5_AH, cT5OU = crown.T5_OU;
      const iAH = crown.initial_AH, iOU = crown.initial_OU;
      if (!cT5AH || !cT5OU) continue;  // 4 條聲道全部要 T-5 皇冠盤，冇就 skip
      const ctx = { m, cT5AH, cT5OU, iAH, iOU, timeBk: timeBucket(m.kickoff_utc) };

      for (const ch of CHANNELS) {
        // TG 為 source of truth: 只要當時真 TG 過就計入
        const ruleId = CHID2RULE[ch.id];
        if (!ruleId || !notifiedSet.has(`${m.sid}::${ruleId}`)) continue;
        if (ruleId === "ch-N2") {
          const currentVersion = (n2NotifiedAt.get(m.sid) || 0) >= n2VersionAt;
          if (currentVersion === !!ch.archived) continue;
        }
        // FIX 2026-09-17: skip disabled rule (歷史數據唔顯示)
        if (disabledRuleIds.has(ruleId) && !ch.archived) continue;
        const crownSrc = ch.market === "AH" ? cT5AH : cT5OU;
        const pinSrc = ch.market === "AH" ? pin.T5_AH : pin.T5_OU;
        const hkjcSrc = ch.market === "AH" ? hkjc.T5_AH : hkjc.T5_OU;
        const crownLine = crownSrc.handicap;
        const crownOdds = ch.side === "H" || ch.side === "O" ? toDec(crownSrc.home_odds) : toDec(crownSrc.away_odds);
        const crownRes = ch.market === "AH" ? gradeAH(m.home_score, m.away_score, crownLine, ch.side) : gradeOU(m.home_score, m.away_score, crownLine, ch.side);
        const crownPnl = pnl(crownRes, crownOdds);
        let pinLine = null, pinOdds = null, pinRes = "NO_PIN", pinPnl = null;
        if (pinSrc) {
          pinLine = pinSrc.handicap;
          pinOdds = ch.side === "H" || ch.side === "O" ? toDec(pinSrc.home_odds) : toDec(pinSrc.away_odds);
          pinRes = ch.market === "AH" ? gradeAH(m.home_score, m.away_score, pinLine, ch.side) : gradeOU(m.home_score, m.away_score, pinLine, ch.side);
          pinPnl = pnl(pinRes, pinOdds);
        }
        let hkjcLine = null, hkjcOdds = null, hkjcRes = "NO_HKJC", hkjcPnl = null;
        if (hkjcSrc) {
          hkjcLine = hkjcSrc.handicap;
          // hkjc_snapshots 已係 decimal · 唔用 +1
          hkjcOdds = ch.side === "H" || ch.side === "O" ? parseFloat(hkjcSrc.home_odds) : parseFloat(hkjcSrc.away_odds);
          if (!isFinite(hkjcOdds) || hkjcOdds <= 0) hkjcOdds = null;
          hkjcRes = ch.market === "AH" ? gradeAH(m.home_score, m.away_score, hkjcLine, ch.side) : gradeOU(m.home_score, m.away_score, hkjcLine, ch.side);
          hkjcPnl = hkjcOdds != null ? pnl(hkjcRes, hkjcOdds) : null;
        }
        games.push({
          sid: m.sid, league: m.league, home: m.home, away: m.away,
          kickoff_utc: m.kickoff_utc, hour_hkt: hourHKT(m.kickoff_utc), time_bucket: ctx.timeBk,
          home_score: m.home_score, away_score: m.away_score, total_score: m.home_score + m.away_score,
          channel: ch.id, channel_label: ch.label, rule_id: ruleId, archived: !!ch.archived,
          ...(ruleId === "ch-N2" ? {
            rule_version: ch.archived ? "N2-v1" : "N2-AM8-v2",
            notified_at: n2NotifiedAt.get(m.sid) || null,
          } : {}),
          bet: { market: ch.market, side: ch.side, display: ch.display },
          crown: { line: crownLine, odds: crownOdds, result: crownRes, pnl: crownPnl },
          pinnacle: { line: pinLine, odds: pinOdds, result: pinRes, pnl: pinPnl },
          hkjc: { line: hkjcLine, odds: hkjcOdds, result: hkjcRes, pnl: hkjcPnl },
        });
      }
    }

    // Summary
    const chStat = () => ({ n:0, W:0, HW:0, P:0, HL:0, L:0, crown_pnl:0, pin_pnl:0, pin_samples:0, hkjc_pnl:0, hkjc_samples:0 });
    const summary = {
      total_games: games.length,
      unique_matches: new Set(games.map(g=>g.sid)).size,
      by_day: {},
      by_channel: { "B∩I": chStat(), "A+低盤": chStat(), "新2": chStat(), "受讓075買細": chStat(),
        "受讓075買細（舊版已停用）": chStat(), "新2（舊版已停用）": chStat() },
      overall: { crown_pnl: 0, pin_pnl: 0, pin_samples: 0, hkjc_pnl: 0, hkjc_samples: 0 },
    };
    for (const g of games) {
      const day = new Date(g.kickoff_utc + 8*3600*1000).toISOString().slice(0,10);
      if (!summary.by_day[day]) summary.by_day[day] = { games:0, crown_pnl:0, pin_pnl:0, pin_games:0, hkjc_pnl:0, hkjc_games:0 };
      summary.by_day[day].games++;
      summary.by_day[day].crown_pnl += (g.crown.pnl || 0);
      const cs = summary.by_channel[g.channel];
      cs.n++;
      if (g.crown.result in cs) cs[g.crown.result]++;
      cs.crown_pnl += (g.crown.pnl || 0);
      summary.overall.crown_pnl += (g.crown.pnl || 0);
      if (g.pinnacle.pnl != null) {
        cs.pin_pnl += g.pinnacle.pnl;
        cs.pin_samples++;
        summary.overall.pin_pnl += g.pinnacle.pnl;
        summary.overall.pin_samples++;
        summary.by_day[day].pin_pnl += g.pinnacle.pnl;
        summary.by_day[day].pin_games++;
      }
      if (g.hkjc && g.hkjc.pnl != null) {
        cs.hkjc_pnl += g.hkjc.pnl;
        cs.hkjc_samples++;
        summary.overall.hkjc_pnl += g.hkjc.pnl;
        summary.overall.hkjc_samples++;
        summary.by_day[day].hkjc_pnl += g.hkjc.pnl;
        summary.by_day[day].hkjc_games++;
      }
    }
    // Add hit rate + ROI per channel
    for (const chId of Object.keys(summary.by_channel)) {
      const cs = summary.by_channel[chId];
      const eff = cs.n - cs.P;
      cs.hit_rate = eff > 0 ? (cs.W + cs.HW) / eff : 0;
      cs.crown_roi = cs.n > 0 ? cs.crown_pnl / (cs.n * STAKE) : 0;
      cs.pin_roi = cs.pin_samples > 0 ? cs.pin_pnl / (cs.pin_samples * STAKE) : 0;
      cs.hkjc_roi = cs.hkjc_samples > 0 ? cs.hkjc_pnl / (cs.hkjc_samples * STAKE) : 0;
    }
    res.writeHead(200, { "content-type": "application/json" });
    return res.end(JSON.stringify({
      generated_at: now,
      window: { start: startTime, end: now },
      min_t5_dec: MIN_T5,
      stake_per_bet: STAKE,
      strategy_name: "4 條聲道",
      note: "皇冠 T-5 觸發 · 同場多聲道分別開注",
      summary, games,
    }));
  } catch (e) {
    res.writeHead(500);
    return res.end("strategy err: " + e.message);
  }
}

formatter_before:
function formatHeavyMsg(hit) {
  const flag = flagFor(hit.league);
  const ko = formatKickoffHKT(hit.kickoff_utc);
  const lines = [
    "🎯 <b>重心頁 · 未開賽</b>",
    "",
    // 球賽 + 聯賽 同一 line（用   防 wrap）
    `${flag} <b>${escapeHtml(hit.league||"")}</b> · ${escapeHtml(hit.home)} vs ${escapeHtml(hit.away)}`,
    `⏰ 開賽 ${ko} HKT`,
    "",
    `📊 <b>命中規則 (${hit.rules.length}):</b>`,
  ];
  for (const r of hit.rules) {
    const pct = (r.hit_rate*100).toFixed(1) + "%";
    const dir = r.direction === "fade" ? "⚠️ 反向" : "🎯 順向";
    // rule bullet 同一 line（用   防 wrap）
    // multi_dim rule 用 rule.label（已含條件描述）；legacy sw rule 用 line_pat + lean_pat
    let condDesc;
    if ((r.type === "multi_dim" || r.id === "ch-BI" || String(r.id).startsWith("ch-U075-")) && r.label) {
      condDesc = (r.id === "ch-BI" || String(r.id).startsWith("ch-U075-")) ? escapeHtml(r.label) : r.label;
    } else {
      const marketLine = `${r.market} ${r.line_pat||""}`.trim();
      const leanStr = r.lean_pat ? `lean ${r.lean_pat}` : "";
      condDesc = [marketLine, leanStr, r.pick||""].filter(Boolean).join(" · ");
    }
    // hit_display 已含 CI 下限 + 保守賠率，唔再 append pct 避免重覆
    const displayStr = r.hit_display || `${(r.hit_rate*100).toFixed(1)}%`;
    lines.push(`• ${[dir, r.id, condDesc, displayStr].filter(Boolean).join(" · ")}`);
  }
  const r0 = hit.rules[0];
  const m = r0.match || {};
  if (m.t5Dec && m.pickLabel) {
    lines.push("");
    // Pinnacle T-5 line 短寫（fallback 用 lineLabel 截取）
    // AH 顯示用市場慣例（睇邊隊 vs 讓幾多）：
    //   DB 負 = 主讓、正 = 主受讓。買主保留；買客才反轉至客隊角度。
    // OU 保持原樣（大細總入球）
    const rMarket = r0.market || "OU";
    const pickSide = m.pick; // "home" | "away"
    const signLineMarket = (v) => {
      const f = parseFloat(v);
      if (!isFinite(f)) return String(v);
      if (rMarket !== "AH") return String(f);
      const displayed = (pickSide === "home") ? f : -f;
      if (displayed > 0) return `+${displayed}`;
      if (displayed === 0) return "0";
      return String(displayed);
    };
    const pinLineRaw = m.t5Line != null ? m.t5Line : ((m.line || "").toString().split(" ").pop() || "");
    const pinLineShort = signLineMarket(pinLineRaw);
    // 查皇冠 T-5 (實際落注)
