function formatHeavyMsg(hit) {
  const flag = flagFor(hit.league);
  const ko = formatKickoffHKT(hit.kickoff_utc);
  const lines = [
    "🎯 <b>重心頁 · 未開賽</b>",
    "",
    // 球賽 + 聯賽 同一 line（用   防 wrap）
    `${flag} <b>${escapeHtml(hit.league||"")}</b> · ${escapeHtml(hit.home)} vs ${escapeHtml(hit.away)}`,
    `⏰ 開賽 ${ko} HKT`,
    "",
    `📊 <b>命中規則 (${hit.rules.length}):</b>`,
  ];
  for (const r of hit.rules) {
    const pct = (r.hit_rate*100).toFixed(1) + "%";
    const dir = r.direction === "fade" ? "⚠️ 反向" : "🎯 順向";
    // rule bullet 同一 line（用   防 wrap）
    // multi_dim rule 用 rule.label（已含條件描述）；legacy sw rule 用 line_pat + lean_pat
    let condDesc;
    if ((r.type === "multi_dim" || r.id === "ch-BI" || r.id === "ch-N2" || String(r.id).startsWith("ch-U075-")) && r.label) {
      condDesc = (r.id === "ch-BI" || r.id === "ch-N2" || String(r.id).startsWith("ch-U075-")) ? escapeHtml(r.label) : r.label;
    } else {
      const marketLine = `${r.market} ${r.line_pat||""}`.trim();
      const leanStr = r.lean_pat ? `lean ${r.lean_pat}` : "";
      condDesc = [marketLine, leanStr, r.pick||""].filter(Boolean).join(" · ");
    }
    // hit_display 已含 CI 下限 + 保守賠率，唔再 append pct 避免重覆
    const displayStr = r.hit_display || `${(r.hit_rate*100).toFixed(1)}%`;
    lines.push(`• ${[dir, r.id, condDesc, displayStr].filter(Boolean).join(" · ")}`);
  }
  const r0 = hit.rules[0];
  const m = r0.match || {};
  if (m.t5Dec && m.pickLabel) {
    lines.push("");
    // Pinnacle T-5 line 短寫（fallback 用 lineLabel 截取）
    // AH 顯示用市場慣例（睇邊隊 vs 讓幾多）：
    //   DB 負 = 主讓、正 = 主受讓。買主保留；買客才反轉至客隊角度。
    // OU 保持原樣（大細總入球）
    const rMarket = r0.market || "OU";
    const pickSide = m.pick; // "home" | "away"
    const signLineMarket = (v) => {
      const f = parseFloat(v);
      if (!isFinite(f)) return String(v);
      if (rMarket !== "AH") return String(f);
      const displayed = (pickSide === "home") ? f : -f;
      if (displayed > 0) return `+${displayed}`;
      if (displayed === 0) return "0";
      return String(displayed);
    };
    const pinLineRaw = m.t5Line != null ? m.t5Line : ((m.line || "").toString().split(" ").pop() || "");
    const pinLineShort = signLineMarket(pinLineRaw);
    // 查皇冠 T-5 (實際落注)
    const crown = lookupCrownT5(hit.signal, rMarket, m.t5Line, m.pick);
    if (crown) {
      const crownLineShort = signLineMarket(crown.line);
      lines.push(`💰 <b>推介:</b> ${m.pickLabel} ${crownLineShort} @ ${crown.dec.toFixed(2)}`);
      if (String(r0.id || "").startsWith("ch-")) {
        const pin = hit.signal?.snapshots?.[`T5_${rMarket}`];
        const pinRaw = pin && (m.pick === "home" || m.pick === "over" ? pin.home : pin.away);
        const sameLine = pin && Number(pin.h) === Number(m.t5Line);
        lines.push(sameLine && pinRaw != null && Number.isFinite(Number(pinRaw))
          ? `   皇冠 T-5 賠率 (實際落注) · Pinnacle 同盤參考 @ ${(Number(pinRaw)+1).toFixed(2)}`
          : "   皇冠 T-5 賠率 (實際落注) · 平博未有同盤 T-5 參考");
      } else {
        lines.push(`   皇冠 T-5 賠率 (實際落注) · Pinnacle 參考 @ ${m.t5Dec.toFixed(2)}`);
      }
    } else {
      lines.push(`💰 <b>推介:</b> ${m.pickLabel} ${pinLineShort}`);
      lines.push(`   皇冠 T-5 未有盤 · Pinnacle @ ${m.t5Dec.toFixed(2)}`);
    }
    // 皇冠短碼 + 主頁 link（配合 /crown-radar/install 書籤用）
    const dl = crownDirectLink(hit.home, hit.away, rMarket, pickSide);
    if (dl) {
      lines.push("");
      lines.push(`📋 短碼（複製）: <code>${escapeHtml(hit.home)}|${escapeHtml(hit.away)}|${dl.sel}</code>`);
      lines.push(`🏦 <a href="${CROWN_BASE_URL}">開皇冠</a> → 揀「今日」→ 撳「開皇冠盤」書籤 → 貼短碼`);
    }
  }
  return lines.join("\n");
}

live_before:
if (url.pathname === "/api/four-channels-live") {
  // 今日已 fire · 未完場 live 表
  // 邏輯：搵 kickoff_utc 喺【今日 HKT 00:00 - 明天 HKT 00:00】區間、has_crown=1、has T-5 crown snapshot
  //       跑 4 條 channel rule matcher，返 fire 出嚟嘅場（唔理有無完場、有無 heavy_notified、有無賽果）
  // 提供 3 層資料：fired(match+rule) / kickoff / current status
  try {
    // use top-level import of matchAll
    const nowMs = Date.now();
    // HKT 當日 window: today 00:00 HKT → tomorrow 00:00 HKT
    const HKT_OFFSET = 8 * 3600_000;
    const localNow = new Date(nowMs + HKT_OFFSET);
    const dayStartHKT = Date.UTC(localNow.getUTCFullYear(), localNow.getUTCMonth(), localNow.getUTCDate()) - HKT_OFFSET;
    const dayEndHKT = dayStartHKT + 24 * 3600_000;

    // Load 4 channel rules from rules.json
    let allRules;
    try { allRules = JSON.parse(fs.readFileSync("./data/rules.json", "utf-8")); }
    catch { allRules = { rules: [] }; }
    const channelRules = (allRules.rules || []).filter(r => ["ch-BI","ch-Alow","ch-N2","ch-U075-v2"].includes(r.id));

    const matches = db.prepare(`
      SELECT m.sid, m.league, m.home, m.away, m.kickoff_utc,
             f.home_score, f.away_score, f.status
      FROM matches m
      LEFT JOIN finished_matches f ON f.sid = m.sid
      WHERE m.has_crown = 1 AND m.kickoff_utc >= ? AND m.kickoff_utc < ?
      ORDER BY m.kickoff_utc ASC
    `).all(dayStartHKT, dayEndHKT);

    const sids = matches.map(m => m.sid);
    const crownBy = new Map();
    if (sids.length) {
      const q = sids.map(()=>"?").join(",");
      for (const r of db.prepare(`SELECT sid,stage,market,handicap,home_odds,away_odds,captured_at FROM crown_snapshots WHERE sid IN (${q})`).all(...sids)) {
        if (!crownBy.has(r.sid)) crownBy.set(r.sid, {});
        crownBy.get(r.sid)[`${r.stage}_${r.market}`] = { h: r.handicap, home: r.home_odds, away: r.away_odds, captured_at: r.captured_at };
      }
    }
    // fetch heavy_notified for tg_sent flag
    const notifiedSet = new Set();
    if (sids.length) {
      const q = sids.map(()=>"?").join(",");
      for (const r of db.prepare(`SELECT sid FROM heavy_notified WHERE sid IN (${q})`).all(...sids)) notifiedSet.add(r.sid);
    }

    const newNotifiedSet = new Set(db.prepare("SELECT sid FROM heavy_notified_rule WHERE rule_id=?").all("ch-U075-v2").map(r => r.sid));
    const fires = [];
    for (const mm of matches) {
      const snapDict = crownBy.get(mm.sid) || {};
      const m = {
        sid: mm.sid, league: mm.league, home: mm.home, away: mm.away,
        kickoff_utc: mm.kickoff_utc,
        snapshots: {
          initial_OU: snapDict["initial_OU"], T30_OU: snapDict["T30_OU"], T5_OU: snapDict["T5_OU"],
          initial_AH: snapDict["initial_AH"], T30_AH: snapDict["T30_AH"], T5_AH: snapDict["T5_AH"],
        },
        sublines: {},
      };
      const hits = matchAll(m, channelRules);
      if (!hits.length) continue;
      const t5AH = snapDict["T5_AH"], t5OU = snapDict["T5_OU"];
      const kickoffMs = mm.kickoff_utc;
      const minsToKickoff = Math.round((kickoffMs - nowMs) / 60000);
      let statusLabel;
      if (mm.status === "完" && mm.home_score != null && mm.away_score != null) statusLabel = `完 ${mm.home_score}-${mm.away_score}`;
      else if (minsToKickoff > 5) statusLabel = `未開波 (T-${minsToKickoff})`;
      else if (minsToKickoff > -5) statusLabel = `T-5 window`;
      else if (minsToKickoff > -110) statusLabel = `進行中 (開波 ${-minsToKickoff}m)`;
      else statusLabel = `已結束 · 未收賽果`;
      for (const h of hits) {
        const rule = h.rule;
        const bookSide = rule.market === "OU" ? (rule.side === "O" ? "over" : "under") : (rule.side === "H" ? "home" : "away");
        const snap = rule.market === "OU" ? t5OU : t5AH;
        const bookPrice = snap ? (bookSide === "over" || bookSide === "home" ? snap.home : snap.away) : null;
        const bookDec = bookPrice != null ? Math.round((parseFloat(bookPrice)+1)*1000)/1000 : null;
        const line = snap ? snap.h : null;
        fires.push({
          sid: mm.sid,
          league: mm.league,
          home: mm.home,
          away: mm.away,
          kickoff_hkt: new Date(mm.kickoff_utc + HKT_OFFSET).toISOString().slice(11,16),
          rule_id: rule.id,
          rule_label: rule.label || rule.id,
          market: rule.market,
          side_display: rule.pick_label || rule.side,
          line,
          price_dec: bookDec,
          status: statusLabel,
          home_score: mm.home_score,
          away_score: mm.away_score,
          tg_sent: rule.id === "ch-U075-v2" ? newNotifiedSet.has(mm.sid) : notifiedSet.has(mm.sid),
        });
      }
    }
    res.writeHead(200, { "content-type": "application/json; charset=utf-8" });
    return res.end(JSON.stringify({
      generated_at: new Date().toISOString(),
      hkt_date: new Date(nowMs + HKT_OFFSET).toISOString().slice(0,10),
      scanned: matches.length,
      fired: fires.length,
      rows: fires,
    }));
  } catch (e) {
    res.writeHead(500);
    return res.end("live err: " + e.message);
  }
}

